    },
    {
      "headline": "King Felipe VI inaugurates CaixaResearch Institute in Barcelona and visits Naval Base Rota amid busy institutional week",
      "summary": "Felipe VI had an intensive institutional agenda: he inaugurated Barcelona's CaixaResearch Institute (Spain's first centre dedicated to immunology) alongside Catalan president Salvador Illa; visited Naval Base Rota to inspect the Armada's aviation flotilla and its ongoing transformation; received Portugal's new president Seguro at the Palacio Real with an unusual gesture breaking protocol; and attended a Cervantes Prize lunch for Mexican author Gonzalo Celorio where he acknowledged 'much abuse' during the Conquest. He also participated in an AI and democracy event at La Granja and is confirmed to preside over the Armed Forces Day in Vigo in late May. Pope Francis's upcoming Canary Islands visit will also include Felipe VI."
    },
    {
      "headline": "Viral celebrity anecdotes from King's Cervantes Prize lunch generate soft-news media storm",
      "summary": "Multiple entertainment and general-interest outlets published and recycled the story of writer Juan del Val (Premio Planeta 2025) recounting his conversation with Felipe VI at the Cervantes Prize lunch at the Palacio Real, where the King asked him about the pressures of TV fame and recommended a documentary on Ukraine. The story generated extensive celebrity-style coverage across Spanish media."
    },
    {
      "headline": "Kitchen corruption trial: Rajoy, Cospedal testify as CNI's alleged role in Bárcenas spying examined",
      "summary": "Former PP prime minister Mariano Rajoy and former party secretary María Dolores de Cospedal appeared before the Audiencia Nacional in the 'Kitchen' case—a suspected state-sponsored operation to spy on PP treasurer Bárcenas. The CNI's alleged involvement, previously denied, came under renewed scrutiny as Soraya Sáenz de Santamaría—who controlled the CNI while in government—was also called as a witness."
    },
    {
      "headline": "Ex-CNI agents testify that PSOE 'fixer' Leire Díez asked them for damaging information on UCO commander",
      "summary": "Two former CNI agents testified before a Madrid judge investigating Leire Díez (described as a PSOE political operative or 'fontanera') that she did not identify herself as a journalist in a 2024 meeting and appeared to seek 'dirty laundry' on UCO anti-corruption unit commander Antonio Balas. The case raises questions about whether CNI agents were illegally recorded during the meeting."
    }
  ]
}

